// Custom Worker entry: the OpenNext app plus our Durable Object class.
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import { default as handler } from "./.open-next/worker.js";

// D1 read replication (Sessions API). Each request runs on a D1 session, so reads can go to a nearby replica.
// The session's bookmark is kept in a short cookie: the next request starts from it, so a user always sees their
// own writes (a saved activity, a changed group) even if the nearest replica is a moment behind. Without the
// cookie, any replica will do. When replication is off for the database, every query goes to the primary.
const BOOKMARK_COOKIE = "aw_d1";
const BOOKMARK_MAX_AGE_SECONDS = 60 * 60;

function readBookmark(request: Request): string | null {
  const match = request.headers.get("Cookie")?.match(new RegExp(`(?:^|;\\s*)${BOOKMARK_COOKIE}=([^;]+)`));
  return match ? decodeURIComponent(match[1]) : null;
}

export default {
  async fetch(request, env, ctx) {
    const incoming = readBookmark(request);
    const session = env.DB.withSession(incoming ?? "first-unconstrained");
    // Drizzle only calls prepare() and batch(), which the session has; getDb() reads env.DB through OpenNext.
    const response: Response = await handler.fetch(request, { ...env, DB: session as unknown as D1Database }, ctx);

    const bookmark = session.getBookmark();
    if (!bookmark || bookmark === incoming || response.status === 101) return response;
    const withCookie = new Response(response.body, response);
    withCookie.headers.append(
      "Set-Cookie",
      `${BOOKMARK_COOKIE}=${encodeURIComponent(bookmark)}; Path=/; Max-Age=${BOOKMARK_MAX_AGE_SECONDS}; HttpOnly; Secure; SameSite=Lax`,
    );
    return withCookie;
  },
} satisfies ExportedHandler<CloudflareEnv>;

export { RateLimiter } from "./src/worker/rate-limiter";
